solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
void tree_free(tree_node *r) {
    if (!r)
        return;
    tree_free(r->left);
    tree_free(r->right);
    free(r->value);
    free(r);
}
static tree_node *build(const char *const *p, const char *const *i, size_t n,
                        bool *ok) {
    if (!n)
        return NULL;
    size_t k = 0;
    while (k < n && strcmp(p[0], i[k]))
        k++;
    if (k == n) {
        *ok = false;
        return NULL;
    }
    tree_node *r = (tree_node *)calloc(1, sizeof(tree_node));
    r->value = (char *)malloc(strlen(p[0]) + 1);
    strcpy(r->value, p[0]);
    r->left = build(p + 1, i, k, ok);
    r->right = build(p + k + 1, i + k + 1, n - k - 1, ok);
    return r;
}
bool tree_from_traversals(const char *const *p, const char *const *i, size_t n,
                          tree_node **out) {
    *out = NULL;
    for (size_t a = 0; a < n; a++)
        for (size_t b = a + 1; b < n; b++)
            if (!strcmp(p[a], p[b]) || !strcmp(i[a], i[b]))
                return false;
    bool ok = true;
    *out = build(p, i, n, &ok);
    if (!ok) {
        tree_free(*out);
        *out = NULL;
    }
    return ok;
}
bool tree_from_traversals_checked(const char *const *p, size_t pn, const char *const *i,
                                  size_t in, tree_node **out) {
    if (pn != in) {
        *out = NULL;
        return false;
    }
    return tree_from_traversals(p, i, pn, out);
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}

int main(void) {
    const char *p[] = {"a", "b", "d", "c"}, *i[] = {"d", "b", "a", "c"};
    tree_node *r;
    assert(tree_from_traversals(p, i, 4, &r));
    assert(!strcmp(r->left->left->value, "d") && !strcmp(r->right->value, "c"));
    tree_free(r);
    const char *q[] = {"a", "a"};
    assert(!tree_from_traversals(q, q, 2, &r));
    const char *z[] = {"z"};
    assert(!tree_from_traversals(p, z, 1, &r));
    assert(tree_from_traversals(NULL, NULL, 0, &r) && !r);
    assert(!tree_from_traversals_checked(p, 4, i, 3, &r) && !r);
    assert(!tree_from_traversals_checked(p, 3, i, 4, &r) && !r);
    assert(tree_from_traversals_checked(p, 4, i, 4, &r));
    tree_free(r);

    return 0;
}
